#!/usr/bin/env bash
# Source this file in shells or launchers that intentionally use privacy-engine.

_pe_add_no_proxy() {
  local value="${1:-}"
  local entry
  for entry in localhost 127.0.0.1 ::1; do
    case ",${value}," in
      *",${entry},"*) ;;
      *) value="${value:+${value},}${entry}" ;;
    esac
  done
  printf '%s' "${value}"
}

export NO_PROXY="$(_pe_add_no_proxy "${NO_PROXY:-${no_proxy:-}}")"
export no_proxy="${NO_PROXY}"

_pe_trust_env="${PE_TRUST_ENV_FILE:-${HOME}/.config/privacy-engine/trust.env}"
if [[ -r "${_pe_trust_env}" ]]; then
  # Generated by pe-trust.sh and contains only quoted export assignments.
  # shellcheck disable=SC1090
  source "${_pe_trust_env}"
fi
unset _pe_trust_env
unset -f _pe_add_no_proxy
